def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        return float(min(budget, 18.0))

    prev_bids = []
    strong_threat = 0.0
    desperate_threat = 0.0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('budget', 0) > 0:
                if bid > strong_threat:
                    strong_threat = float(bid)
                if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                    if bid > desperate_threat:
                        desperate_threat = float(bid)

    active_rivals = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) > 0:
            active_rivals += 1

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    urgency = 0
    if hp <= 2 or no_water_days >= 2:
        urgency = 3
    elif hp <= 4 or no_water_days >= 1:
        urgency = 2
    elif hp <= 6:
        urgency = 1

    if active_rivals <= 1:
        base = 12.0 if urgency == 0 else 28.0
    else:
        if scarcity == 2:
            base = 62.0
        elif scarcity == 1:
            base = 44.0
        else:
            base = 24.0

    if prev_bids:
        highest_prev = max(prev_bids)
    else:
        highest_prev = 0.0

    target = base

    if urgency >= 3:
        target = max(target, highest_prev + 3.0, desperate_threat + 2.0, 78.0)
    elif urgency == 2:
        target = max(target, min(highest_prev + 2.0, 95.0), 56.0)
    elif scarcity >= 1:
        target = max(target, min(strong_threat + 1.5, 88.0))
    else:
        if highest_prev >= 120.0:
            target = min(target, 22.0)
        elif highest_prev >= 70.0:
            target = min(max(target, 18.0), 30.0)
        else:
            target = max(target, 20.0)

    if day >= 8 and hp > 4 and no_water_days == 0:
        target *= 0.9
    if day >= 8 and urgency >= 2:
        target *= 1.1

    reserve = 0.0
    if hp > 4 and no_water_days == 0:
        reserve = 35.0
    elif hp > 2:
        reserve = 20.0

    cap = max(0.0, budget - reserve)
    if urgency >= 2:
        cap = budget

    bid = min(target, cap)

    if urgency >= 3 and bid < min(budget, 65.0):
        bid = min(budget, 65.0)
    if bid < 0:
        bid = 0.0

    return float(round(min(budget, bid), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate previous_trace
    prev_bids = []
    prev_hp_after = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass
            try:
                prev_hp_after.append(float(prev.get('hp_after', o.get('hp', 0.0))))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Pressure estimate: if someone paid near/above typical salary, they likely contested aggressively.
    aggressive = highest_prev_bid >= DAILY_SALARY * 0.85

    # Supply pressure: with higher supply, water is cheaper; with lower supply, bid more.
    # Normalize between MIN_SUPPLY and MAX_SUPPLY.
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Base bid target
    # If aggressive: shade below their top bid to avoid overpaying while still contesting.
    # If not aggressive: bid enough to secure water when needed.
    if aggressive:
        # Shade factor: bid slightly below the highest previous bid but scale with my needs.
        need_factor = 1.0
        if my_hp <= 2.0 or my_no_water_days >= 2:
            need_factor = 1.25
        elif my_hp >= 7.0 and my_no_water_days <= 0:
            need_factor = 0.85
        target = highest_prev_bid * 0.92 * need_factor
    else:
        # When not aggressive, bid around a fraction of salary, more if supply is tight.
        tightness = 1.0 - supply_norm  # 1 at MIN_SUPPLY, 0 at MAX_SUPPLY
        target = DAILY_SALARY * (0.45 + 0.25 * tightness)
        if my_hp <= 2.0 or my_no_water_days >= 2:
            target *= 1.35
        if my_hp >= 7.0 and my_no_water_days <= 0:
            target *= 0.9

    # Ensure we don't bid more than budget; also add a small floor to avoid zero bids.
    # If my budget is very low, conserve.
    if my_budget <= 0.0:
        return 0.0

    # Soft cap relative to budget
    cap = my_budget

    # If my HP is critical, prioritize survival even if it means spending.
    if my_hp <= 1.5 or my_no_water_days >= 3:
        # Spend aggressively but not exceeding budget
        return max(0.0, min(cap, DAILY_SALARY * 0.95))

    # If my HP is moderate and budget allows, bid near target.
    bid = min(cap, target)

    # If supply is extremely low, ensure bid is not too small.
    if supply <= float(MIN_SUPPLY):
        bid = max(bid, DAILY_SALARY * 0.55)

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
